from lib import *
S = SS('h3')
steps = [
    step("服务端主动返回 0 到 16 共 17 个状态码,客户端收到的 code 与线上最后 trailers 里的 grpc-status 数字完全一致:OK 0、Canceled 1、Unknown 2、InvalidArgument 3、DeadlineExceeded 4、NotFound 5、AlreadyExists 6、PermissionDenied 7、ResourceExhausted 8、FailedPrecondition 9、Aborted 10、OutOfRange 11、Unimplemented 12、Internal 13、Unavailable 14、DataLoss 15、Unauthenticated 16。这 17 个就是 gRPC 的全部状态码,数字不会变,线上传的是数字,名字是各语言库自己的。", t=tl(S(1)), done=lidx(S(1), '16   Unauthenticated'), mark=lidx(S(1), '0    OK'), b=bars([['状态码个数', 17, '17'], ['最大编号', 16, '16']], 18, done=[0, 1]), kv=KV([['OK', '0'], ['Unavailable', '14(最常需要重试)'], ['Unauthenticated', '16(最大编号)']], ['Unavailable'])),
    step("服务端返回的不是 status 的错误时:返回普通 errors.New(“普通 error,不是 status”),客户端看到 code=Unknown,message 就是错误文本;返回 context.Canceled,客户端看到 Canceled;返回 context.DeadlineExceeded,客户端看到 DeadlineExceeded;返回 fmt.Errorf 包了一层的 status.Error(NotFound),客户端仍然看到 NotFound,message 是 “包了一层: rpc error: code = NotFound desc = 内层 NotFound”——grpc-go 会拆开 %w 包装拿到里面的 status。想让客户端拿到有意义的 code,服务端必须返回 status 错误,普通 error 一律变成 Unknown。", t=tl(S(2)), done=lidx(S(2), '服务端返回 wrapped'), mark=lidx(S(2), '服务端返回 plain'), b=bars([['plain → Unknown(2)', 2, 'Unknown'], ['context.Canceled → Canceled(1)', 1, 'Canceled'], ['context.DeadlineExceeded → 4', 4, 'DeadlineExceeded'], ['包装的 NotFound → 5', 5, 'NotFound']], 6, done=[1, 2, 3], mark=[0]), kv=KV([['普通 error', '→ Unknown'], ['context 错误', '→ Canceled / DeadlineExceeded'], ['%w 包装的 status', '→ 保留内层 code(NotFound)']], ['普通 error'])),
    step("框架自己产生的状态码:调用没注册的方法 → Unimplemented,message “unknown method NoSuchMethod for service demo.Demo”;服务端要 2 秒、客户端 200 ms 超时 → DeadlineExceeded(用时 201.1 ms);客户端 100 ms 后取消 → Canceled(101.1 ms);服务端不存在(端口没人监听),默认 fail-fast → Unavailable,用时 0.4 ms,message 里是 “connect: connection refused”;同样的调用加 WaitForReady(true) → 不再立刻失败,等到截止时间才返回 DeadlineExceeded(801.1 ms),message 是 “latest balancer error: …connection refused”。连接失败默认是 Unavailable;想等服务起来要显式 WaitForReady。", t=tl(S(3)), done=lidx(S(3), '同样但加 WaitForReady'), mark=lidx(S(3), '服务端不存在'), b=bars([['fail-fast 用时 ms', 0.4, '0.4'], ['WaitForReady 用时 ms', 801.1, '801.1'], ['客户端超时 200 ms 实际用时', 201.1, '201.1'], ['客户端取消 100 ms 实际用时', 101.1, '101.1']], 810, mark=[0], done=[1]), kv=KV([['连接失败', 'Unavailable,0.4 ms 返回'], ['WaitForReady(true)', '等到截止时间,DeadlineExceeded'], ['没注册的方法', 'Unimplemented']], ['连接失败'])),
    step("一个不说 gRPC 的 HTTP/2 服务器(比如网关或代理)返回 HTTP 状态时,客户端的映射:200(没有 grpc-status)→ Unknown;400 → Internal;401 → Unauthenticated;403 → PermissionDenied;404 → Unimplemented;429 → Unavailable;500 → Unknown;502、503、504 → Unavailable。message 里带着 “unexpected HTTP status code received from server: 502 (Bad Gateway); transport: received unexpected content-type \"text/html\"” 和响应体。所以网关超时 504 和限流 429 在客户端都是 Unavailable,可以重试;500 却是 Unknown。排查时要看 message,不能只看 code。", t=tl(S(4)), done=lidx(S(4), '502        Unavailable'), mark=lidx(S(4), '500        Unknown'), b=bars([['400 → Internal(13)', 13, 'Internal'], ['401 → Unauthenticated(16)', 16, 'Unauthenticated'], ['404 → Unimplemented(12)', 12, 'Unimplemented'], ['502/503/504/429 → Unavailable(14)', 14, 'Unavailable'], ['500 → Unknown(2)', 2, 'Unknown']], 17, done=[3], mark=[4]), kv=KV([['429、502、503、504', '→ Unavailable'], ['400', '→ Internal'], ['500 与 200(无 grpc-status)', '→ Unknown']], ['429、502、503、504'])),
]
A = mkarth('h3', 3, 'gRPC,状态码,错误处理,Unavailable,WaitForReady,HTTP 状态映射,Go,真实验证,动画演示',
    '实测 gRPC 的 17 个状态码:线上传的是数字;普通 error 一律变成 Unknown;连接失败默认立刻返回 Unavailable(0.4 ms),加 WaitForReady 才会等;网关返回 429/502/503/504 在客户端都是 Unavailable,500 却是 Unknown。',
    '返回错误的时候该用哪个状态码?哪些是框架自己产生的?网关吐出 HTTP 状态时客户端怎么翻译?这篇把 17 个状态码逐个走一遍,再看几个容易踩的映射。',
    [('17 个', 'gRPC 的状态码总数,编号 0 到 16,线上传的是数字'), ('0.4 对 801.1 ms', '连接被拒绝时,默认 fail-fast 与加 WaitForReady(true) 的返回时间'), ('Unavailable', '网关返回 429、502、503、504 时客户端得到的状态码(500 是 Unknown)')],
    [('线上的状态码', '<p>状态码在最后 trailers 的 grpc-status 里,是 0 到 16 的数字。实测服务端返回任何一个,客户端看到的名字与线上数字一一对应。</p>'),
     ('服务端返回什么', '<p>返回普通 error 一律变成 Unknown;返回 context.Canceled 或 context.DeadlineExceeded 会变成对应的 Canceled、DeadlineExceeded;用 %w 包装的 status 错误会被拆开,保留内层 code。想让调用方能区分错误,就返回 status.Error。</p>'),
     ('框架产生的', '<p>没有这个方法是 Unimplemented;超时是 DeadlineExceeded;客户端取消是 Canceled;连不上服务是 Unavailable。连不上默认立刻失败(0.4 ms),加 WaitForReady(true) 会等到截止时间再返回 DeadlineExceeded。</p>'),
     ('网关与 HTTP 状态', '<p>如果路径上有一个不说 gRPC 的 HTTP/2 服务,客户端按 HTTP 状态映射:401 是 Unauthenticated、403 是 PermissionDenied、404 是 Unimplemented、429/502/503/504 是 Unavailable、400 是 Internal,而 500 和没有 grpc-status 的 200 都是 Unknown。网关的行为会直接影响客户端的重试判断(第 18 篇)。</p>')],
    steps,
    [ENV_H + '。第四节的“不说 gRPC 的服务器”是 golang.org/x/net/http2/h2c 起的明文 HTTP/2 服务,每次返回指定的 HTTP 状态和一小段 HTML;所有结果是确定的,耗时是单次测量',
     '没有验证:Java 或 C++ 客户端的映射是否相同(这里只测了 grpc-go v1.84.0);服务端 panic 时的行为;错误详情 details 的传递(第 22 篇);状态码和重试策略的结合(第 18 篇);拦截器对状态码的改写;HTTP/1.1 网关(不支持 trailers)返回的情况'],
    '状态码')
